sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float count;
uniform float width;
uniform float angle;
uniform float phase;
layout(color) uniform half4 color;
uniform float punch;
uniform float smoothing;
uniform float screenSpace;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 patternSize = screenSpace > 0.5 ? screen.zw : size;
    float2 origin = screenSpace > 0.5 ? screen.xy + screen.zw * 0.5 : size * 0.5;
    float a = radians(angle);
    float period = patternSize.y / (2.475 * max(count, 0.5));
    float u = dot(coord - origin, float2(-sin(a), cos(a))) / period + phase;
    float e = abs(fract(u) - 0.5);
    float edge = max(smoothing * 0.5, 0.5 * 1.0 / period);
    float s = 1.0 - smoothstep(width * 0.5 - edge, width * 0.5 + edge, e);
    s *= step(0.0001, width);
    if (punch > 0.5) return src * half(1.0 - s);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, float3(color.rgb), s * float(color.a));
    return half4(half3(rgb) * src.a, src.a);
}
